"""Deterministic Merkabah perspective rotation.

This stage does not assert what any stakeholder actually believes. It creates
explicit questions from several viewpoints so the later mirror and boundary
stages do not reason from a single angle.
"""

from __future__ import annotations

from pydantic import BaseModel

PERSPECTIVE_KEYS = (
    "user",
    "opposite",
    "developer",
    "legal_consent",
    "affected_party",
    "future_self",
    "system",
    "adversarial",
)


class MerkabahRotation(BaseModel):
    """Questions generated by rotating a task through bounded viewpoints."""

    user: str
    opposite: str
    developer: str
    legal_consent: str
    affected_party: str
    future_self: str
    system: str
    adversarial: str

    def as_dict(self) -> dict[str, str]:
        return self.model_dump()


def rotate_perspectives(task: str) -> MerkabahRotation:
    """Return a deterministic set of perspective questions for *task*.

    The output is deliberately interrogative. It identifies considerations to
    verify; it is not evidence and must not be treated as stakeholder consent,
    legal advice, or a factual prediction.
    """
    if not isinstance(task, str):
        raise TypeError("task must be str")

    text = task.strip() or "(empty task)"
    short = (text[:120] + "…") if len(text) > 120 else text

    return MerkabahRotation(
        user=f"User view: what outcome and constraint matter most in: {short}",
        opposite=(
            "Opposite view: what would a reasonable case against this action "
            f"or its assumptions say about: {short}"
        ),
        developer=(
            "Developer view: what inputs, dependencies, failure modes, tests, "
            "and rollback path are required?"
        ),
        legal_consent=(
            "Legal/consent view: what authority, permission, jurisdiction, or "
            "professional verification must be confirmed?"
        ),
        affected_party=(
            "Affected-party view: who experiences the consequences, and what "
            "expectations, privacy, or consent must be respected?"
        ),
        future_self=(
            "Future-self view: after the immediate result, what maintenance, "
            "reversibility, precedent, and downstream effects remain?"
        ),
        system=(
            "System view: how does this change project state, memory, tools, "
            "permissions, auditability, and later decisions?"
        ),
        adversarial=(
            "Adversarial view: how could ambiguity, misuse, false assumptions, "
            "or missing authorization turn this into harm?"
        ),
    )


__all__ = ["PERSPECTIVE_KEYS", "MerkabahRotation", "rotate_perspectives"]
